// Distanza dal centro (asse Y) per gli anelli
float dist = pModel.y;

// 'fract' crea strisce nette (anelli); -u_time li espande verso l'esterno
float anelli = fract(dist * 10.0 - ubuf.u_time * 2.0);

// Bordi leggermente sfumati
anelli = smoothstep(0.0, 0.2, anelli) * smoothstep(1.0, 0.8, anelli);

// Fondo = u_col2, anelli = u_col1 (colori del dock)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, anelli);
